"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["89797"],{6122(e){e.exports=JSON.parse('{"id":"FIN-735","slug":"net-asset-value","term":"Net Asset Value (NAV)","also_known_as":["NAV"],"difficulty":"Intermediate","definition":"Net asset value (NAV) is the value of an investment fund\'s assets minus its liabilities, usually expressed per unit or share of the fund.","explanation":["NAV tells investors what each unit of a fund is worth. It is calculated by adding up the market value of all the fund\'s investments and cash, subtracting liabilities such as fees owed, and dividing by the number of units outstanding.","For example, a fund holding investments worth 105 million, with liabilities of 5 million and 10 million units outstanding, has a NAV of 10.00 per unit.","Mutual funds are usually bought and sold at their NAV, which is typically calculated once a day after markets close. An investor placing an order during the day receives that day\'s closing NAV.","Exchange-traded funds and closed-end funds also report a NAV, but their shares trade on stock exchanges at market prices that can differ from NAV. When the market price is above NAV, the fund trades at a premium; when below, at a discount. For most large exchange-traded funds, the gap is very small, but for closed-end funds it can be significant.","A fund\'s NAV rising over time reflects growth in its investments, while distributions of income or gains reduce the NAV by the amount paid out."],"note":"","total":1500,"prev":{"slug":"neobank","term":"Neobank"},"next":{"slug":"net-debt","term":"Net Debt"}}')}}]);